import{_ as a,o as s,c as o,ag as i}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"nay_lib","description":"","frontmatter":{},"headers":[],"relativePath":"pt/nay-lib/index.md","filePath":"pt/nay-lib/index.md"}'),r={name:"pt/nay-lib/index.md"};function t(n,e,d,l,c,p){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="nay-lib" tabindex="-1">nay_lib <a class="header-anchor" href="#nay-lib" aria-label="Permalink to &quot;nay_lib&quot;">​</a></h1><p>O <code>nay_lib</code> é a biblioteca partilhada por trás de todos os scripts Nayretis. Recebe-o em cada compra, instala-o uma única vez, e cada script Nayretis que adicionar passa a usá-lo.</p><h2 id="o-que-oferece" tabindex="-1">O que oferece <a class="header-anchor" href="#o-que-oferece" aria-label="Permalink to &quot;O que oferece&quot;">​</a></h2><ul><li><strong>Um único painel de definições</strong>, <code>/nay</code>, para todos os scripts Nayretis. As definições ficam guardadas na sua base de dados e são aplicadas a todos os jogadores assim que as guarda. Consulte <a href="/pt/nay-lib/panel">Painel /nay</a>.</li><li><strong>Permissões</strong> por ACE ou por identificador Discord, Steam, FiveM ou license. Consulte <a href="/pt/nay-lib/permissions">Permissões</a>.</li><li><strong>Seis idiomas</strong>: inglês, francês, espanhol, português, polaco e alemão. Uma tradução em falta aparece em inglês.</li><li><strong>Bridge de frameworks</strong>: ESX Legacy, QBCore, QBox e ox_core detetados automaticamente, com os respetivos inventários, targets e notificações. Consulte <a href="/pt/bridge/">Bridge</a>.</li><li><strong>API HTTP</strong> para o seu site, painel ou bot do Discord, desativada por predefinição. Consulte <a href="/pt/nay-lib/api">API HTTP</a>.</li><li><strong>Webhooks</strong>, incluindo mensagens no Discord, para os eventos dos scripts. Consulte <a href="/pt/nay-lib/webhooks">Webhooks</a>.</li><li><strong>Registo</strong> de todas as alterações feitas no jogo, pela consola ou pela API. Consulte <a href="/pt/nay-lib/audit">Registo</a>.</li><li>Notificações, avisos de texto e barras de progresso da Nayretis, partilhados por todos os scripts.</li></ul><h2 id="requisitos-e-ordem-de-arranque" tabindex="-1">Requisitos e ordem de arranque <a class="header-anchor" href="#requisitos-e-ordem-de-arranque" aria-label="Permalink to &quot;Requisitos e ordem de arranque&quot;">​</a></h2><p>A única dependência é o <a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>. Inicie o <code>nay_lib</code> depois dos recursos de framework, inventário e target, e antes de todos os scripts Nayretis:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span></code></pre></div><p>As tabelas são criadas no primeiro arranque. As opções de servidor que ficam no <code>server.cfg</code> estão listadas na página <a href="/pt/nay-lib/convars">Convars</a>.</p>`,8)])])}const m=a(r,[["render",t]]);export{g as __pageData,m as default};
